// Код для ноды Prepare Vacancies (Function)

const input = items[0] && items[0].json ? items[0].json : {};
let body = input.body || input.response || input.data || input;

// Если пришла строка, парсим
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) { body = {}; }
}

// Достаем массив вакансий
const itemsArr = Array.isArray(body.items) ? body.items : (Array.isArray(body.vacancies) ? body.vacancies : []);

// Берем только 3 шт (или сколько указано в limit)
const limit = Math.min(10, Number(items[0]?.json?.per_page || 10));
const sliced = itemsArr.slice(0, limit);

// Функция очистки текста
function cleanText(s) {
  if (!s || typeof s !== 'string') return '';
  return s
    .replace(/<highlighttext[^>]*>([\s\S]*?)<\/highlighttext>/gi, '$1')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// Формируем единый текстовый контекст + список ссылок
let fullText = "";
let linksBlock = "\n=== СПИСОК ССЫЛОК ДЛЯ ОТЧЕТА ===\n";

sliced.forEach((v, index) => {
  const name = cleanText(v.name);
  const url = v.alternate_url || v.url || "Нет ссылки";
  // Формируем описание
  const desc = cleanText(v.description || (v.snippet ? (v.snippet.requirement + " " + v.snippet.responsibility) : ""));

  fullText += `--- ВАКАНСИЯ №${index + 1}: ${name} ---\n`;
  fullText += `${desc}\n\n`;

  // Добавляем в блок ссылок
  linksBlock += `${index + 1}. ${name} - ${url}\n`;
});

// Склеиваем всё вместе
fullText += linksBlock;

// Если вакансий нет
if (!fullText.trim()) fullText = "Вакансий не найдено.";

// Возвращаем ОДИН элемент
return [{
  json: {
    input_text_for_ai: fullText,
    vacancies_count: sliced.length
  }
}];

// Парсим ответ от AI
const output = items[0].json.output || items[0].json.text || "";
let parsed = {};

try {
  if (typeof output === 'string') {
     const cleanJson = output.replace(/```json/g, '').replace(/```/g, '').trim();
     parsed = JSON.parse(cleanJson);
  } else {
     parsed = output;
  }
} catch (e) {
  return [{ json: { digest_text: output } }];
}

return [{ json: { digest_text: parsed.digest_text || "Не удалось сформировать дайджест." } }];
